/// Writes a synthetic profile directory and returns it.
Future<Directory> writeProfile(Directory root, {String prefs = prefsJs, String? filters = filterRules}) async {
  await File(p.join(root.path, 'prefs.js')).writeAsString(prefs);
  if (filters != null) {
    final dir = Directory(p.join(root.path, 'ImapMail', 'mail.example.test'));
    await dir.create(recursive: true);
    await File(p.join(dir.path, 'msgFilterRules.dat')).writeAsString(filters);
  }
  return root;
}

class InMemoryRuleStore implements SortRuleStore {
  final Map<String, SortRule> rules = {};
  @override
  Future<List<SortRule>> load(String accountId) async =>
      rules.values.where((r) => r.accountId == accountId).toList()..sort((a, b) => a.priority.compareTo(b.priority));
  @override
  Future<void> upsert(SortRule r, DateTime now) async => rules[r.id] = r;
}
